import {avg} from './engine.mjs';
import {panel,chart} from './ui.mjs';
const usable=v=>(typeof v==='number'||typeof v==='string')&&String(v).trim()!==''&&Number.isFinite(Number(v))&&Number(v)>=0;
// Preserve the established dashboard totals; new curves require complete reported-well fields.
export function groupProductionRows(rows){const out=new Map();for(const r of rows){const a=out.get(r.date)??{date:r.date,oil:0,water:0,injection:0,liquid:0,pressures:[],records:[]};for(const k of ['oil','water','liquid'])a[k]+=Number(r[k]??0);a.injection+=Number(r.injection??0);a.pressures.push(Number(r.pressure));a.records.push(r);out.set(r.date,a);}return [...out.values()].sort((a,b)=>a.date.localeCompare(b.date)).map(({records,...a})=>{const gasMissing=records.filter(r=>!usable(r.gas)).length,oilComplete=records.every(r=>usable(r.oil)),waterComplete=records.every(r=>usable(r.water)),gas=gasMissing?null:records.reduce((s,r)=>s+Number(r.gas),0),oilGasRatio=oilComplete&&gas!==null&&gas>0?a.oil/gas:null;return {...a,pressure:avg(a.pressures),water_cut:a.liquid?a.water/a.liquid*100:0,gas,daily_water:waterComplete?a.water:null,oil_gas_ratio:oilGasRatio,oil_per_10k_gas:oilGasRatio===null?null:oilGasRatio*10000,reported_well_count:new Set(records.map(r=>r.well_id??'未指定')).size,gas_missing_count:gasMissing};});}
export function productionCurvePanels(history){const labels=history.map(r=>r.date);const specs=[{key:'daily_water',title:'日产水动态',name:'日产水观测',unit:'标准立方米/日',color:'#0c98a5',missing:'缺少有效日产水，请上传water字段（标准立方米/日）。',note:'青色实线：日产水；按当前所选井与日期汇总，真实零产水保留为0。'},{key:'gas',title:'日产气动态',name:'日产气观测',unit:'标准立方米/日',color:'#7c55ab',missing:'缺少有效日产气，请上传gas字段（标准立方米/日）；不将缺失值当作零产气。',note:'紫色实线：日产气；当天任一已上报井缺少gas时断线显示，不用不完整总量计算比值。'},{key:'oil_per_10k_gas',title:'油气比动态',name:'油气比（油/气，按万方气折算）',unit:'标准立方米油/万标准立方米气',color:'#bc8640',missing:'缺少有效日产气或日产气为零，不能计算油气比；请补充oil、gas字段。',note:'金色实线：日产油÷日产气×10000；多井先汇总油气量再相除，不平均各井比值。气量为零或缺失时留空。'}];return `<div class="three gap">${specs.map(s=>panel(s.title,history.some(r=>usable(r[s.key]))?chart([{name:s.name,values:history.map(r=>r[s.key]),labels,color:s.color}],{unit:s.unit,label:'生产日期'}):`<div class="empty">${s.missing}</div>`,'',s.note)).join('')}</div>`;}
